(function zcode() {
  function ingestLegacy() {
    const p = path.join(HOME, ".zcode/cli/db/db.sqlite");
    let db;
    try {
      db = new DatabaseSync(p, { readOnly: true });
    } catch {
      return 0;
    }
    const sess = db.prepare("SELECT * FROM session").all();
    const msgs = db.prepare("SELECT * FROM message ORDER BY session_id, sequence").all();
    const parts = db.prepare("SELECT * FROM part ORDER BY session_id, message_id, sequence").all();
    const partsByMsg = new Map();
    for (const pt of parts) {
      let d = {};
      try {
        d = JSON.parse(pt.data);
      } catch {}
      const arr = partsByMsg.get(pt.message_id) || [];
      arr.push(d);
      partsByMsg.set(pt.message_id, arr);
    }
    const msgsBySession = new Map();
    for (const m of msgs) {
      let d = {};
      try {
        d = JSON.parse(m.data);
      } catch {}
      const arr = msgsBySession.get(m.session_id) || [];
      arr.push({ ...m, parsed: d });
      msgsBySession.set(m.session_id, arr);
    }
    let n = 0;
    for (const s of sess) {
      bumpTotal("zcode", s.id);
      const project = projectFromCwd(s.directory);
      if (s.time_deleted) {
        skip("zcode", s.id, s.title, "deleted");
        continue;
      }
      if (isNoiseProject(project)) {
        skip("zcode", s.id, s.title, "scratch_workspace");
        continue;
      }
      const list = msgsBySession.get(s.id) || [];
      const prompts = [];
      const assistants = [];
      const files = new Set();
      const cmds = new Set();
      let toolCalls = 0,
        toolErrors = 0;
      for (const m of list) {
        const role = m.parsed?.role;
        const pl = partsByMsg.get(m.id) || [];
        for (const d of pl) {
          if (d.type === "tool" || d.type === "tool_use" || d.type === "tool-invocation") {
            toolCalls++;
            if (d.state === "error" || d.isError || d.error) toolErrors++;
            const inp = d.input || d.args || {};
            if (typeof inp.file_path === "string") files.add(inp.file_path);
            if (typeof inp.filePath === "string") files.add(inp.filePath);
            if (typeof inp.path === "string" && /\//.test(inp.path)) files.add(inp.path);
            if (typeof inp.command === "string") cmds.add(clip(inp.command, 200));
          }
        }
        const text = pl
          .filter((d) => d.type === "text" && d.text)
          .map((d) => d.text)
          .join("\n");
        if (role === "user" && text) prompts.push(clip(text, MAX_PROMPT));
        if (role === "assistant" && text) assistants.push(text);
      }
      const rec = {
        source: "zcode",
        id: s.id,
        project,
        cwd: s.directory || "",
        title: clean(s.title || ""),
        startedAt: s.time_created ? new Date(Number(s.time_created)).toISOString() : null,
        durationMin:
          s.time_created && s.time_updated
            ? Math.round((Number(s.time_updated) - Number(s.time_created)) / 60000)
            : null,
        model: "",
        mode: s.permission ? JSON.parse(s.permission).mode || "" : "",
        userTurns: prompts.length,
        assistantTurns: assistants.length,
        toolCalls,
        toolErrors,
        filesTouched: [...files].slice(0, MAX_FILES),
        commands: [...cmds].slice(0, 20),
        firstUserPrompts: prompts.slice(0, MAX_PROMPTS),
        assistantDigest: assistants.length ? [clip(assistants[assistants.length - 1], MAX_DIGEST)] : [],
        signals: { outcome: s.last_outcome || "", taskType: s.task_type || "" },
      };
      push(rec);
      n++;
    }
    db.close();
    return n;
  }

  function ingestV2() {
    const p = path.join(HOME, ".zcode/v2/tasks-index.sqlite");
    let db;
    try {
      db = new DatabaseSync(p, { readOnly: true });
    } catch {
      return 0;
    }
    const rows = db
      .prepare(
        "SELECT task_id, title, root_path, execution_directories, searchable_text, model, mode, cli_last_outcome, cli_created_at, cli_updated_at, deleted FROM tasks WHERE deleted=0"
      )
      .all();
    let n = 0;
    for (const s of rows) {
      bumpTotal("zcode", s.task_id);
      const cwd = s.root_path || s.execution_directories || "";
      const project = projectFromCwd(cwd) || projectFromAbsolutePaths([cwd]);
      const text = clean(String(s.searchable_text || ""));
      if (!text || text.length < 20) {
        skip("zcode", s.task_id, s.title, "empty_transcript");
        continue;
      }
      if (isNoiseProject(project)) {
        skip("zcode", s.task_id, s.title, "scratch_workspace");
        continue;
      }
      const chunks = text.split(/\n(?=[\u4e00-\u9fffA-Za-z0-9@\[])/).filter((x) => x.trim().length > 2);
      const prompts = [];
      const assistants = [];
      for (let i = 0; i < chunks.length; i++) {
        const c = chunks[i].trim();
        if (!c) continue;
        if (i === 0 || c.length < 80) prompts.push(clip(c, MAX_PROMPT));
        else assistants.push(c);
      }
      const files = new Set(
        [...text.matchAll(/\S+\.(vue|js|ts|jsx|tsx|scss|css|json|html|conf|config|xml|sql|wxml|wxss)/gi)].map((m) => m[0])
      );
      const started = s.cli_created_at ? new Date(Number(s.cli_created_at)).toISOString() : null;
      const rec = {
        source: "zcode",
        id: s.task_id,
        project: project || "unknown",
        cwd,
        title: clean(s.title || prompts[0] || "").slice(0, 120),
        startedAt: started,
        durationMin:
          s.cli_created_at && s.cli_updated_at
            ? Math.round((Number(s.cli_updated_at) - Number(s.cli_created_at)) / 60000)
            : null,
        model: s.model || "zcode",
        mode: s.mode || "",
        userTurns: Math.max(1, prompts.length),
        assistantTurns: Math.max(assistants.length ? 1 : 0, assistants.length),
        toolCalls: 0,
        toolErrors: 0,
        filesTouched: [...files].slice(0, MAX_FILES),
        commands: [],
        firstUserPrompts: prompts.slice(0, MAX_PROMPTS),
        assistantDigest: assistants.length ? [clip(assistants[assistants.length - 1], MAX_DIGEST)] : [clip(text.slice(-MAX_DIGEST), MAX_DIGEST)],
        signals: { outcome: s.cli_last_outcome || "", v2: true },
      };
      if (rec.project === "unknown") {
        skip("zcode", s.task_id, rec.title, "no_project");
        continue;
      }
      push(rec);
      n++;
    }
    db.close();
    return n;
  }

  ingestLegacy();
  ingestV2();
})();

