/**
 * 本地 agent 历史 → OpenViking 导入（按 source 顺序）
 * 用法: node import-local-sources.mjs [--skip-extract]
 * 顺序: zcode(opencode) → workbuddy → cursor
 */
import fs from "fs";
import path from "path";
import { spawnSync } from "child_process";
import os from "os";

const BASE = path.join(os.homedir(), "Documents/deepseek-harness/default-workspace/memory-migration");
const OUT = path.join(BASE, "out");
const NODE = process.execPath;
const TMP = path.join(os.tmpdir());
const BATCH = 4;
const GAP = 5000;

const SOURCES = [
  { key: "zcode", label: "OpenCode/zcode" },
  { key: "workbuddy", label: "WorkBuddy" },
  { key: "cursor", label: "Cursor" },
];

const SKIP_EXTRACT = process.argv.includes("--skip-extract");

function run(script, args = [], env = {}) {
  const r = spawnSync(NODE, [path.join(BASE, script), ...args], {
    cwd: BASE,
    encoding: "utf8",
    env: { ...process.env, ...env },
    stdio: ["ignore", "pipe", "pipe"],
    maxBuffer: 50 * 1024 * 1024,
  });
  return r;
}

function loadSessions() {
  const p = path.join(OUT, "sessions.jsonl");
  return fs
    .readFileSync(p, "utf8")
    .split(/\n/)
    .filter(Boolean)
    .map((l) => JSON.parse(l));
}

function projectsForSource(rows, source) {
  const m = new Map();
  for (const r of rows) {
    if (r.source !== source || !r.project) continue;
    m.set(r.project, (m.get(r.project) || 0) + 1);
  }
  return [...m.entries()].sort((a, b) => a[1] - b[1]);
}

function patchEvidence(distillRoot, sourceKey) {
  const root = path.join(distillRoot);
  if (!fs.existsSync(root)) return 0;
  let n = 0;
  for (const proj of fs.readdirSync(root)) {
    const d = path.join(root, proj);
    if (!fs.statSync(d).isDirectory()) continue;
    for (const f of fs.readdirSync(d).filter((x) => x.endsWith(".json"))) {
      const fp = path.join(d, f);
      const j = JSON.parse(fs.readFileSync(fp, "utf8"));
      let changed = false;
      for (const m of j.memories || []) {
        if (!m.evidence || m.evidence.startsWith("草稿")) {
          m.evidence = `extracted source=${sourceKey} project=${proj}`;
          changed = true;
        }
        m.project = m.project || proj;
      }
      if (changed) {
        fs.writeFileSync(fp, JSON.stringify(j, null, 1), "utf8");
        n++;
      }
    }
  }
  return n;
}

function countMemories(distillRoot, project) {
  const d = path.join(distillRoot, project);
  if (!fs.existsSync(d)) return 0;
  let n = 0;
  for (const f of fs.readdirSync(d).filter((x) => x.endsWith(".json"))) {
    const j = JSON.parse(fs.readFileSync(path.join(d, f), "utf8"));
    n += (j.memories || []).length;
  }
  return n;
}

if (!SKIP_EXTRACT) {
  console.log("[1/4] extract 刷新 sessions.jsonl …");
  const ex = run("scripts/extract.mjs");
  if (ex.status !== 0) {
    console.error(ex.stderr?.slice(-500) || ex.stdout?.slice(-500));
    process.exit(1);
  }
  console.log(ex.stdout.trim().slice(-400));
}

const allRows = loadSessions();
const state = { startedAt: new Date().toISOString(), sources: {} };

for (const { key, label } of SOURCES) {
  console.log(`\n======== ${label} (${key}) ========`);
  const projs = projectsForSource(allRows, key);
  if (!projs.length) {
    console.log("  无有效项目，跳过");
    state.sources[key] = { skipped: true, reason: "no projects" };
    continue;
  }
  const distillRoot = path.join(OUT, "distilled-local", key);
  fs.mkdirSync(distillRoot, { recursive: true });
  const srcState = { projects: projs.length, imported: 0, memories: 0, details: [] };

  for (const [project, sessN] of projs) {
    console.log(`\n--- ${project} (${sessN} sessions) ---`);
    const br = run("scripts/build-bundles-multi.mjs", [project], { MM_SOURCE_FILTER: key });
    if (br.status !== 0) {
      console.error("  bundle fail:", br.stderr?.slice(-200));
      srcState.details.push({ project, error: "bundle" });
      continue;
    }
    const dr = run("scripts/distill-draft.mjs", [project], { MM_DISTILL_ROOT: distillRoot });
    if (dr.status !== 0) {
      console.error("  distill fail:", dr.stderr?.slice(-200));
      srcState.details.push({ project, error: "distill" });
      continue;
    }
    patchEvidence(distillRoot, key);
    const memN = countMemories(distillRoot, project);
    if (!memN) {
      console.log("  0 条新记忆（可能已被 knownTitles 去重），跳过导入");
      srcState.details.push({ project, memories: 0, skipped: true });
      continue;
    }
    const doneFile = path.join(TMP, `done-ov-${key}-${project}.json`);
    const srcDir = path.join(distillRoot, project);
    const ir = run("import-to-ov.mjs", [
      project,
      `--batch=${BATCH}`,
      `--gap=${GAP}`,
      `--src=${srcDir}`,
      `--done=${doneFile}`,
      `--skip=${doneFile}`,
    ]);
    process.stdout.write(ir.stdout || "");
    if (ir.stderr) process.stderr.write(ir.stderr);
    if (ir.status !== 0) {
      srcState.details.push({ project, memories: memN, error: "import", code: ir.status });
    } else {
      srcState.imported++;
      srcState.memories += memN;
      srcState.details.push({ project, memories: memN, ok: true });
    }
  }
  state.sources[key] = srcState;
  console.log(`\n${label} 小结: 项目 ${srcState.imported}/${projs.length} 成功, 约 ${srcState.memories} 条记忆`);
}

state.finishedAt = new Date().toISOString();
const statePath = path.join(TMP, "import-local-sources-state.json");
fs.writeFileSync(statePath, JSON.stringify(state, null, 2), "utf8");
console.log(`\n状态: ${statePath}`);

